#!/usr/bin/env bash
# deploy_dekrb_stage3.sh (v2) — CANLI dosyalari acikca hedefler (kok, sonra shells/); backups/ ASLA. Idempotent, node --check, build+recreate.
set -e
cd /opt/krb-assessment
TS=$(date +%s)
for kv in "nav:" "srv:" "bi:" "saha:" "app:"; do
  echo "${kv#*:}" | base64 -d > /tmp/p_${kv%%:*}.py
done
# CANLI dosya: once kok (./), sonra shells/. backups/ HARIC.
pick(){ for p in "./$1" "shells/$1" "public/$1"; do case "$p" in *backups*) continue;; esac; [ -f "$p" ] && { echo "$p"; return 0; }; done; return 1; }
SRV=$(pick server_container.mjs) || { echo "HATA: server_container.mjs yok"; exit 1; }
BIJS=$(pick bi.js)               || { echo "HATA: bi.js yok"; exit 1; }
SAHA=$(pick saha.js)             || { echo "HATA: saha.js yok"; exit 1; }
APP=$(pick app.js)               || { echo "HATA: app.js yok"; exit 1; }
echo "CANLI dosyalar:"; for f in "$SRV" "$BIJS" "$SAHA" "$APP"; do ls -la "$f"; done
case "$SRV$BIJS$SAHA$APP" in *backups*) echo "HATA: backups yolu secildi, iptal"; exit 1;; esac
for f in "$SRV" "$BIJS" "$SAHA" "$APP"; do cp "$f" "$f.bak.$TS"; done
echo "--- server ---";  python3 /tmp/p_srv.py  "$SRV";  node --check "$SRV"  && echo "  ✓ server ok"
echo "--- bi.js ---";   python3 /tmp/p_nav.py  "$BIJS" || true; python3 /tmp/p_bi.py "$BIJS"; node --check "$BIJS" && echo "  ✓ bi ok"
echo "--- saha.js ---"; python3 /tmp/p_saha.py "$SAHA"; node --check "$SAHA" && echo "  ✓ saha ok"
echo "--- app.js ---";  python3 /tmp/p_app.py  "$APP";  node --check "$APP"  && echo "  ✓ app ok"
grep -q "alici = 'KRB'" "$SRV" && echo "  ✓ SQL veri-degeri (alici='KRB') korundu" || echo "  UYARI: alici='KRB' yok"
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -25 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "BITTI. Stage 3 canli."
